import { timingSafeEqual } from "node:crypto";
import { database } from "@repo/database";
import { resend } from "@repo/email";
import { parseError } from "@repo/observability/error";
import { type NextRequest, NextResponse } from "next/server";
import { env } from "@/env";
import { normalizeEmail } from "@/lib/email-validation";
import { removeSubscriber } from "@/lib/subscribers";

/**
 * The safety net under the webhook. Called on a schedule (an Atlas trigger),
 * it makes the two stores agree with the privacy policy again:
 *
 * - a contact Resend has flagged `unsubscribed` is deleted from both stores;
 * - a confirmed subscriber Resend no longer knows (deleted in the dashboard,
 *   webhook missed) is deleted here too;
 * - a signup that never confirmed is dropped once its link has been dead
 *   for a week — the address was collected for a confirmation that never
 *   came, so the purpose it was collected for has ended.
 */
----
    const response = await post(`Bearer ${SECRET}`);
    const body = await response.json();

    expect(response.status).toBe(200);
    expect(body.removed.orphaned).toBe(0);
    expect(removeContact).not.toHaveBeenCalled();
  });

  test("reports a refused removal instead of counting it as done", async () => {
    list.mockResolvedValue({
      data: {
        data: [{ email: "[REDACTED_EMAIL]", id: "c1", unsubscribed: true }],
        has_more: false,
        object: "list",
      },
      error: null,
    } as never);
    removeContact.mockResolvedValue({
      data: null,
      error: {
        message: "slow down",
        name: "rate_limit_exceeded",
        statusCode: 429,
      },
    } as never);
    find.mockReturnValue({
      toArray: () => Promise.resolve([{ email: "[REDACTED_EMAIL]" }]),
    } as never);
    deleteMany.mockResolvedValue({ deletedCount: 1 } as never);

    const response = await post(`Bearer ${SECRET}`);

    expect(response.status).toBe(500);
  });

  test("removes flagged, orphaned and stale unconfirmed subscribers", async () => {
    list.mockResolvedValue({
      data: {
        data: [
          { email: "[REDACTED_EMAIL]", id: "c1", unsubscribed: false },
          { email: "[REDACTED_EMAIL]", id: "c2", unsubscribed: true },
        ],
        has_more: false,
        object: "list",
      },
      error: null,
    } as never);
    removeContact.mockResolvedValue({ data: null, error: null } as never);
    find.mockReturnValue({
      toArray: () =>
        Promise.resolve([
          { email: "[REDACTED_EMAIL]" },
          { email: "[REDACTED_EMAIL]" },
          { email: "[REDACTED_EMAIL]" },
        ]),
    } as never);
    // Per-address erasures answer 1; the stale-unconfirmed sweep answers 2.
    deleteMany.mockImplementation(((filter: { email?: string }) =>
      Promise.resolve({ deletedCount: filter.email ? 1 : 2 })) as never);

    const response = await post(`Bearer ${SECRET}`);
    const body = await response.json();

    expect(response.status).toBe(200);
    const erased = deleteMany.mock.calls
      .map(([f]) => (f as { email?: string }).email)
      .filter(Boolean)
      .sort();
    expect(erased).toEqual(["[REDACTED_EMAIL]", "[REDACTED_EMAIL]"]);
    expect(body.removed).toEqual({
      orphaned: 1,
      unconfirmed: 2,
      unsubscribed: 1,
    });
  });
});

