import "./styles.css";
import { AnalyticsProvider } from "@repo/analytics/provider";
import { DesignSystemProvider } from "@repo/design-system";
import { cn } from "@repo/design-system/lib/utils";
import { Toolbar } from "@repo/feature-flags/components/toolbar";
import type { Metadata } from "next";
import type { ReactNode } from "react";
import { jetbrainsMono, switzer } from "@/app/fonts";
import { env } from "@/env";

// Resolves every page's relative /api/og image to an absolute URL in the
// rendered og:image tag — crawlers don't do relative. Pages set their own
// title and description; this is the floor under the ones that don't.
export const metadata: Metadata = {
  description: "The unofficial live playground for Next.js and Vercel.",
  metadataBase: new URL(env.NEXT_PUBLIC_WEB_URL),
  title: "hasToggle — the unofficial live playground for Next.js & Vercel",
};

interface RootLayoutProperties {
  readonly children: ReactNode;
}

const RootLayout = ({ children }: RootLayoutProperties) => (
  // Switzer and JetBrains Mono are the marketing faces, so this app declares
  // them once at the root rather than layering them over the design system's
  // Geist. Loading both pairs meant preloading ~141 KB of Geist that the
  // marketing tree overrides on the very next element and never paints.
  <html
    className={cn(
      switzer.variable,
      jetbrainsMono.variable,
      "touch-manipulation scroll-smooth font-sans antialiased"
    )}
    // The attribute must accompany scroll-smooth: the router only suppresses
    // smooth scrolling during route-transition scroll resets when it sees it
    // (it won't pay getComputedStyle to find out). Without it, every page
    // navigation animates its scroll-to-top from the old position. Hash
    // scrolls are exempt from the suppression, so anchors keep the glide.
    data-scroll-behavior="smooth"
    lang="en"
    suppressHydrationWarning
  >
    <body>
      <AnalyticsProvider>
        <DesignSystemProvider>{children}</DesignSystemProvider>
      </AnalyticsProvider>
      <Toolbar />
    </body>
  </html>
);

export default RootLayout;
----
/*
 * PostHog used to be a static import in this file. Next.js bundles
 * instrumentation-client into a chunk it runs *before* hydration, so that put
 * roughly 315 KB of analytics on the critical path: the browser downloaded,
 * parsed and executed the whole SDK — which then fetched surveys, web-vitals
 * and dead-click autocapture from PostHog's CDN — before the page could paint
 * its main content or respond to input.
 *
 * Nothing in the SDK needs to run that early. A `$pageview` is captured
 * relative to `init`, not to navigation start, so deferring init past the
 * `load` event keeps the same events while taking the bytes out of the path
 * that first paint and interactivity share. The only thing lost is a visit
 * that ends before `load` fires, which would not have reached the network
 * either way.
 *
 * The keys are read straight from `process.env` rather than through
 * `keys()`: Next inlines `NEXT_PUBLIC_*` at build time, and `keys()` would
 * pull zod and @t3-oss/env into this pre-hydration chunk just to re-check
 * two constants. Apps validate them server-side by calling `keys()` there.
 */

const startPostHog = async () => {
  const { default: posthog } = await import("posthog-js");

  const key = process.env.NEXT_PUBLIC_POSTHOG_KEY;
  if (!key) {
    return;
  }

  posthog.init(key, {
    api_host: process.env.NEXT_PUBLIC_POSTHOG_HOST,
    defaults: "2025-05-24",
    // Surveys are not in use; this skips a 34 KB script fetched after load.
    disable_surveys: true,
  });
};

// Idle if the browser offers it, next tick otherwise. The timeout stops the
// callback being starved indefinitely on a page that never goes quiet.
const whenIdle = (task: () => void) => {
  if (typeof window.requestIdleCallback === "function") {
    window.requestIdleCallback(task, { timeout: 3000 });
    return;
  }
  window.setTimeout(task, 1);
};

export const initializeAnalytics = () => {
  if (typeof window === "undefined") {
    return;
  }

  if (document.readyState === "complete") {
    whenIdle(startPostHog);
    return;
  }

  window.addEventListener("load", () => whenIdle(startPostHog), { once: true });
};

